    {"folder_name": "PLAN_ORC_PROTHEUS_FULL", "sql_query": "select (Z0.ZAB_ANO + '|' + Z0.ZAB_MES + '|' + Z0.ZAB_FILENT + '|' + Z0.ZAB_CC + '|' + Z0.ZAB_IC + '|' + Z0.ZAB_CONTA + '|' + str(Z0.ZAB_VERSAO,Len(Z0.ZAB_VERSAO)) ) as SURROGATE_KEY, Left(Z0.ZAB_FILENT,2) as ZAB_EMPRESA, Z0.ZAB_FILENT, Z0.ZAB_ANO, Z0.ZAB_MES, Z0.ZAB_CONTA, Z5.ZA5_DESCRI, Z5.ZA5_CONDIC as ZA5_SINAL, Z0.ZAB_VALOR, Z0.ZAB_CC, Z0.ZAB_IC, Z0.D_E_L_E_T_ AS D_E_L_E_T_, Z0.R_E_C_N_O_ AS R_E_C_N_O_ from ZAB000 Z0 Left Join ZA5000 Z5 on Z5.ZA5_COD = Z0.ZAB_CONTA and Z5.ZA5_FILENT = Z0.ZAB_FILENT and Z5.D_E_L_E_T_ <> '*' where Z0.D_E_L_E_T_ <> '*' and Z0.ZAB_ANO >= 2024 and (Z0.ZAB_ANO + '|' + Z0.ZAB_MES + '|' + Z0.ZAB_FILENT + '|' + Z0.ZAB_CC + '|' + Z0.ZAB_IC + '|' + Z0.ZAB_CONTA + '|' + str(Z0.ZAB_VERSAO,Len(Z0.ZAB_VERSAO)) ) in ( select (Z1.ZAB_ANO + '|' + Z1.ZAB_MES + '|' + Z1.ZAB_FILENT + '|' + Z1.ZAB_CC + '|' + Z1.ZAB_IC + '|' + Z1.ZAB_CONTA + '|' + str(Max(Z1.ZAB_VERSAO), Len(Max(Z1.ZAB_VERSAO))) ) as SK_KEY from ZAB000 Z1 where Z1.D_E_L_E_T_ <> '*' and Z1.ZAB_ANO >= 2024 Group By (Z1.ZAB_ANO + '|' + Z1.ZAB_MES + '|' + Z1.ZAB_FILENT + '|' + Z1.ZAB_CC + '|' + Z1.ZAB_IC + '|' + Z1.ZAB_CONTA) ) and Left(Z0.ZAB_FILENT,2) in ('02','03','04','05','06','09','14','15','16')"},
    {"folder_name": "PLAN_ORC_PROTHEUS_FULL_ALL_VERSIONS", "sql_query": "select (Z0.ZAB_ANO + '|' + Z0.ZAB_MES + '|' + Z0.ZAB_FILENT + '|' + Z0.ZAB_CC + '|' + Z0.ZAB_IC + '|' + Z0.ZAB_CONTA + '|' + str(Z0.ZAB_VERSAO,Len(Z0.ZAB_VERSAO)) ) as SURROGATE_KEY, Left(Z0.ZAB_FILENT,2) as ZAB_EMPRESA, Z0.ZAB_FILENT, Z0.ZAB_ANO, Z0.ZAB_MES, Z0.ZAB_VERSAO, Z0.ZAB_CONTA, Z5.ZA5_DESCRI, Z5.ZA5_CONDIC as ZA5_SINAL, Z0.ZAB_VALOR, Z0.ZAB_CC, Z0.ZAB_IC, Z0.D_E_L_E_T_ AS D_E_L_E_T_, Z0.R_E_C_N_O_ AS R_E_C_N_O_ from ZAB000 Z0 with (nolock) Left Join ZA5000 Z5 with (nolock) on Z5.ZA5_COD = Z0.ZAB_CONTA and Z5.ZA5_FILENT = Z0.ZAB_FILENT and Z5.D_E_L_E_T_ <> '*' where Z0.D_E_L_E_T_ <> '*' and Z0.ZAB_ANO >= 2024 and Left(Z0.ZAB_FILENT,2) in ('02','03','04','05','06','09','14','15','16')"},
